import { describe, it } from "vitest";

// Readings adopted where the specification leaves details open:
// - "first insurance" (+10 %) applies to every quote; "follow-up contract" (-15 %) applies
//   to every quote after the customer's first quote within the scenario.
// - Component blocks are counted per exact component type and apply only when exactly 3
//   components of that type are on the policy.
// - Rejections are observable at the CLI: non-zero exit code, an error description on
//   stderr, and no results on stdout.

describe("quote: base premiums (newcomer, first contract: +10 % first insurance, +5 G fee)", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
  it.todo("plain sword -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("plain amulet -> premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("plain staff -> premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("plain potion -> premium 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("1 rune -> premium 33 G (25 base + 2.5 first insurance + 5 fee = 32.5, rounded up)");
  it.todo("1 moonstone -> premium 33 G (25 base, same as a rune)");
});

describe("quote: building block of 3 alike components", () => {
  it.todo("2 runes -> 50 G base premium -> premium 60 G");
  it.todo("3 runes -> 60 G base premium (block) -> premium 71 G");
  it.todo("4 runes -> 100 G base premium (no block) -> premium 115 G");
  it.todo("7 runes -> 175 G base premium (no block) -> premium 198 G (197.5 rounded up)");
  it.todo("2 runes + 1 moonstone -> 75 G base premium (different types, no block) -> premium 88 G");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two blocks) -> premium 137 G");
});

describe("quote: item-specific modifiers", () => {
  it.todo("newcomer with a cursed steel sword, enchantment 3 -> premium 165 G");
  it.todo("cursed sword + plain amulet -> curse surcharge only on the sword: 160 + 50 + 16 + 5 -> premium 231 G");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 G");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
  it.todo("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G");
  it.todo("cursed sword with enchantment 4 -> only the curse surcharge -> premium 165 G");
});

describe("quote: policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years -> loyalty discount on a plain sword -> premium 95 G");
  it.todo("customer with 1 year -> no loyalty discount on a plain sword -> premium 115 G");
  it.todo("second quote of a newcomer -> follow-up discount: plain sword -> premiums 115 G then 100 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -> premium 160 G");
  it.todo("second quote of a newcomer: cursed sword + 2 runes -> 197.5 G -> premium 198 G (rounded up)");
});

describe("claim: reimbursement clauses", () => {
  it.todo("regular steel sword, enchantment 3, damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G");
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, exactly enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("steel sword, enchantment 9, damage 901 G -> 350.5 G -> payout 350 G (rounded down)");
});

describe("claim: deductible and multiple items", () => {
  it.todo("sword damaged 500 G and amulet damaged 300 G -> payout 600 G, remaining cap 2600 G");
  it.todo("two swords insured, both damaged 500 G -> payout 800 G, remaining cap 3200 G (cap 4000 G)");
  it.todo("claim refers to its policy by step index: amulet policy at step 1, damage 300 G -> payout 200 G, remaining cap 1000 G");
});

describe("claim: cap from insurance values", () => {
  it.todo("sword, two successive claims of 1500 G -> payout 1400 G / cap 600 G, then payout 600 G / cap 0 G");
  it.todo("cursed sword, damage 5000 G -> payout 2000 G, remaining cap 0 G (cap from unmodified value)");
  it.todo("sword + 3 runes, sword damage 5000 G -> payout 3500 G, remaining cap 0 G (insurance sum 1750 G)");
  it.todo("amulet, damage 5000 G -> payout 1200 G (insurance value 600 G)");
  it.todo("staff, damage 5000 G -> payout 1600 G (insurance value 800 G)");
  it.todo("potion, damage 5000 G -> payout 800 G (insurance value 400 G)");
  it.todo("rune, damage 5000 G -> payout 500 G (insurance value 250 G)");
  it.todo("moonstone, damage 5000 G -> payout 500 G (insurance value 250 G)");
});

describe("claim-office CLI", () => {
  it.todo("schema example: 5-year customer, amulet quote then fire claim 200 G -> {results: [{premium: 59}, {payout: 100, remainingCap: 1100}]}");
  it.todo("quote with unknown item type 'broomstick' -> non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim damaging an amulet when only a sword is insured -> non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim damaging an unknown item type -> non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim with two sword damages but one sword insured -> non-zero exit, error on stderr, nothing on stdout");
  it.todo("claim with damage amount -200 -> non-zero exit, error on stderr, nothing on stdout");
});

