cd src && python3 - <<'EOF'
p='claim-office.spec.ts'
s=open(p).read()
s=s.replace('import { describe, it } from "vitest";','''import { describe, expect, it } from "vitest";
import { runScenario, type ItemInput } from "./claim-office.js";

function quotePremiums(years: number, ...quotes: ItemInput[][]): number[] {
  const { results } = runScenario({
    customer: { yearsWithMHPCO: years },
    steps: quotes.map((items) => ({ op: "quote", items })),
  });
  return results.map((result) => ("premium" in result ? result.premium : NaN));
}''',1)
s=s.replace('''  it.todo("empty item list -> premium 5 G (only the processing fee)");''','''  it("empty item list -> premium 5 G (only the processing fee)", () => {
    expect(quotePremiums(0, [])).toEqual([5]);
  });''')
open(p,'w').write(s)
EOF
cd .. && pnpm test 2>&1 | grep -E "Error|Tests|Test Files|expected" | head

