cat > src/claim-office.ts <<'EOF'
export interface ItemInput {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: ItemInput[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export type StepResult = { premium: number };

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: [] };
}
