import type { ItemInput } from "./item.js";
import { quotePremium } from "./premium.js";

export type { ItemInput };

export interface QuoteStep {
  op: "quote";
  items: ItemInput[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export type StepResult = { premium: number };

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}
