import type { ItemInput } from "./item.js";

export interface DamageInput {
  itemType: string;
  amount: number;
}

export interface Policy {
  items: ItemInput[];
  remainingCap: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;
const PERCENT = 100;
const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

function insuranceSum(items: ItemInput[]): number {
  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
}

function reimbursement(item: ItemInput | undefined, amount: number): number {
  if ((item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD) {
    return (amount * HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT) / PERCENT;
  }
  return amount;
}

function damagePayout(policyItems: ItemInput[], damage: DamageInput): number {
  const damagedItem = policyItems.find((item) => item.type === damage.itemType);
  return reimbursement(damagedItem, damage.amount) - DEDUCTIBLE_PER_DAMAGE;
}

function roundPayoutInMHPCOFavor(payout: number): number {
  return Math.floor(payout);
}

export function openPolicy(items: ItemInput[]): Policy {
  return { items, remainingCap: insuranceSum(items) * CAP_MULTIPLIER };
}

export function settleClaim(policy: Policy, damages: DamageInput[]): ClaimResult {
  const desiredPayout = roundPayoutInMHPCOFavor(
    damages.reduce((sum, damage) => sum + damagePayout(policy.items, damage), 0),
  );
  const payout = Math.min(desiredPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
}
import type { ItemInput } from "./item.js";

const PROCESSING_FEE = 5;
const PERCENT = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const LOYALTY_DISCOUNT_PERCENT = 20;
const LOYALTY_MIN_YEARS = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
const COMPONENT_BASE_PREMIUM = 25;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;
const COMPONENT_TYPES = ["rune", "moonstone"];
const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function isComponent(item: ItemInput): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function componentsBasePremium(count: number): number {
  return count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function policyBasePremium(items: ItemInput[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const mainItemsPremium = mainItems.reduce((sum, item) => sum + MAIN_ITEM_BASE_PREMIUMS[item.type], 0);
  const componentsPremium = COMPONENT_TYPES.reduce(
    (sum, type) => sum + componentsBasePremium(items.filter((item) => item.type === type).length),
    0,
  );
  return mainItemsPremium + componentsPremium;
}

function roundPremiumInMHPCOFavor(premium: number): number {
  return Math.ceil(premium);
}

function itemSurchargePercent(item: ItemInput): number {
  const curse = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantment =
    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return curse + highEnchantment;
}

function itemSurchargesInPercentUnits(items: ItemInput[]): number {
  return items
    .filter((item) => !isComponent(item))
    .reduce((sum, item) => sum + MAIN_ITEM_BASE_PREMIUMS[item.type] * itemSurchargePercent(item), 0);
}

export interface CustomerHistory {
  yearsWithMHPCO: number;
  previousContracts: number;
}

function policyModifierPercent(customer: CustomerHistory): number {
  const loyalty = customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS ? -LOYALTY_DISCOUNT_PERCENT : 0;
  const followUp = customer.previousContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT + loyalty + followUp;
}

export function quotePremium(items: ItemInput[], customer: CustomerHistory): number {
  const policyPremiumInPercentUnits = policyBasePremium(items) * (PERCENT + policyModifierPercent(customer));
  return roundPremiumInMHPCOFavor(
    (policyPremiumInPercentUnits + itemSurchargesInPercentUnits(items)) / PERCENT + PROCESSING_FEE,
  );
}
export interface ItemInput {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

